from contextlib import contextmanager
from glob import glob
from inspect import currentframe
from logging import Logger
from os import chdir, path, remove
from os.path import basename
from shutil import make_archive
from threading import Event, Thread

from taf.sw.syslog import syslog as ute_syslog

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.utils.common import check_iphy_vm_trs_ip, is_ip_addr

logger = Logger("LC")
ONE_GiB = 1024**3
FILE_OBSERVER_TIMEOUT = 60


def _create_syslog_instances(_syslog_instances, devices):
    # type: (Dict[ute_syslog, str], Dict[str, List[str]]) -> Iterator[Tuple[ute_syslog, str, str]]
    for hw, ip_addrs in devices.items():
        for ip_addr in ip_addrs:
            if not ip_addr:
                continue
            if not is_ip_addr(ip_addr):
                logger.warning("{} is not correct IP address. Syslog will not be started".format(ip_addr))
                continue
            _syslog = ute_syslog()
            if hw.lower().startswith("iphy"):
                ip_addr = check_iphy_vm_trs_ip(logger) or ip_addr
            _syslog_instances[_syslog] = ip_addr
            yield _syslog, ip_addr, hw


def _compress_and_remove(file_list, log_dir):
    # type: (Set[str], str) -> None
    for file_name in sorted(file_list):
        zip_name = make_archive(
            base_name=path.join(log_dir, file_name[:-4]), format="zip", root_dir=log_dir, base_dir=file_name
        )
        logger.debug("Zip {}".format(zip_name))
        syslog_to_rm = path.join(log_dir, file_name)
        remove(syslog_to_rm)
        logger.debug("Remove: {}".format(syslog_to_rm))


def _compress_finished_logs(log_dir, path_regexp, current_logs, all_files=False):
    # type: (str, str, Set[str], bool) -> Set[str]
    latests_logs = set(glob(r"*_{}_*.log".format(path_regexp)))
    logger.debug("current_logs len: {} : {}".format(len(current_logs), sorted(current_logs)))
    logger.debug("latests_logs len: {} : {}".format(len(latests_logs), sorted(latests_logs)))
    result = set()
    if all_files:
        _compress_and_remove(latests_logs, log_dir)
    elif latests_logs - current_logs:
        common_part = latests_logs & current_logs
        logger.debug("common part: {}".format(sorted(common_part)))
        _compress_and_remove(common_part, log_dir)
        result = latests_logs - current_logs
    return result


def wait_for_new_logs(log_dir, path_regexp, event, timeout):
    # type: (str, str, Event, int) -> None
    """
    Function observing log_dir for new syslog matching path_regexp.
    When new syslog appear previous one will be compressed and deleted.

    :param log_dir: directory where syslog should be stored
    :param path_regexp: regexp for file to observe
    :param event: threading event to set when plugin is about to stop
    :param timeout: event waiting timeout
    """
    chdir(log_dir)
    current_logs = set(glob(r"*_{}_*.log".format(path_regexp)))
    while not event.isSet():
        logger.debug("Current syslogs: {}".format(current_logs))
        event_is_set = event.wait(timeout)
        all_files = False
        if event_is_set:
            all_files = True
        logger.debug("Compress remaining files: {}".format(all_files))
        current_logs = _compress_finished_logs(log_dir, path_regexp, current_logs, all_files)


def _start_compressing_threads(log_dir, devices, event):
    # type: (str, Dict[str, List[str]], Event) -> List[Thread]
    threads = []
    for hw, ip_addrs in devices.items():
        for idx, ip_addr in enumerate(ip_addrs, 1):
            compressing_thread = Thread(
                name="observ_{}_{}".format(hw, idx),
                target=wait_for_new_logs,
                args=(log_dir, "{}_{}".format(hw, ip_addr), event, FILE_OBSERVER_TIMEOUT),
            )
            compressing_thread.start()
            threads.append(compressing_thread)
    return threads


def start(
    _syslog_instances, log_dir, devices, compress, ports=(51000, 51001, 51003, 50011, 51603), host_ip="127.0.0.1"
):
    # type: (Dict[ute_syslog, str], str, Dict[str, List[str]], bool, Tuple[int, ...], str) -> None
    """
    Method should start collecting syslog.

    :param _syslog_instances: dict with syslog instances and ip addresses to be used for that instance
    :param log_dir: directory where syslog should be stored
    :param devices: dict with eNB ip or I-PHY IP address which should be used to listen for syslog.
    :param compress: turn on-the-fly compression of collected syslogs on
    :param ports: ports which should be used to listen for syslog.
    :param host_ip: ip of machine where logs will be stored
    """
    logger.debug("Inside {} before start".format(basename(__file__)))
    file_limit = ONE_GiB if compress else 0
    for _syslog, _ip, hw in _create_syslog_instances(_syslog_instances, devices):
        logger.info("Inside {} for {} before start".format(basename(__file__), _ip))
        logger.debug(
            "Received set of params: log_dir = {}, device = {}, ports = {}, host_ip = {}".format(
                log_dir, _ip, ports, host_ip
            )
        )
        try:
            _syslog.start_syslog(
                log_dir=log_dir,
                log_name="syslog_{}_{}_{}.log".format(SERVER_HOST, hw, _ip),
                ip=_ip,
                ports=ports,
                host_ip=host_ip,
                file_limit=file_limit,
                alias=f"syslog_{_ip}"
            )
        except Exception as exc:
            logger.error("Exception caught upon start_syslog. {}:{}".format(type(exc).__name__, exc), exc_info=True)
            logger.error("Going to stop for {}, start will not be finished.".format(_ip))
            stop({_syslog: _ip}, with_exc=True)
            _syslog_instances.pop(_syslog)
            continue
        logger.info("Inside {} for {} after start".format(basename(__file__), _ip))
    logger.debug("Inside {} after start".format(basename(__file__)))


def stop(_syslog_instances, with_exc=False):
    # type: (Dict[ute_syslog, str], bool) -> None
    """
    Method should stop collecting syslog and store results.

    :param _syslog_instances: dict with syslog instances and ip addresses used for that instance
    :param with_exc: boolean value whether stop() should be handled as exception case or not
    """
    if not _syslog_instances:
        logger.warning("No syslog instances to stop. Check if syslog was started correctly.")
    for _syslog, _ip in _syslog_instances.items():
        logger.info("Inside {} before stop. Exception status = {}".format(basename(__file__), with_exc))
        try:
            if with_exc:
                _syslog.stop_syslog(alias=f"syslog_{_ip}")
                logger.debug("Syslog stopped for {} with exception".format(_ip))
            else:
                _syslog.collect_syslog_results(alias=f"syslog_{_ip}")
                logger.debug("Syslog collected successfully for {}".format(_ip))
        except Exception as exc:
            logger.error("Exception caught upon stop. {}:{}".format(type(exc).__name__, exc), exc_info=True)
        logger.info("Inside {} for {} after stop.".format(basename(__file__), _ip))


def stop_compressing_threads(compressing_threads):
    # type: (List[Thread]) -> None
    """Calls join on all compressing threads to block syslog from exiting with additional thread running."""
    for thread in compressing_threads:
        try:
            thread.join(60)
        except Exception as err:
            logger.debug(err, exc_info=True)


@contextmanager
def syslog(log_host, log_port, ports=(51000, 51001, 51003, 50011, 51601, 51603), host_ip="127.0.0.1", **kwargs):
    # type: (str, int, Tuple[int, ...], str, Dict[str, List[str]]) -> Iterator
    """
    Plugin for gathering syslog. It starts syslog module and yields, waiting to be finished.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param ports: ports which should be used to listen for syslog.
    :param host_ip: ip of machine where logs will be stored
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    compress = kwargs.pop("compress")
    logger.debug(
        "Received set of params: log_dir = {}, compress = {}, ports = {}, host_ip = {}, kwargs = {}".format(
            log_dir, compress, ports, host_ip, kwargs
        )
    )
    _syslog_instances = {}  # type: Dict[syslog, str]
    devices = kwargs
    zip_remaining_logs_ev = Event()
    compressing_threads = None
    try:
        start(_syslog_instances, log_dir, devices, compress, ports, host_ip)
        if compress:
            compressing_threads = _start_compressing_threads(log_dir, devices, zip_remaining_logs_ev)
        yield
    finally:
        stop(_syslog_instances)
        zip_remaining_logs_ev.set()
        if compressing_threads:
            stop_compressing_threads(compressing_threads)
